import{d as r,C as a,o as g,c as d,a3 as t,E as e,j as s,a as h}from"./chunks/framework.Q4yG9rk_.js";const m=JSON.parse('{"title":"正易心法·第三十八章","description":"《正易心法》第三十八章——卦位生数，运以成数：生数一二三四五为阴阳之位（天道，有象无形），成数六七八九十为刚柔之德（地道，有形）；以成数运于生数之上，天地交感，吉凶叶应。","frontmatter":{"title":"正易心法·第三十八章","description":"《正易心法》第三十八章——卦位生数，运以成数：生数一二三四五为阴阳之位（天道，有象无形），成数六七八九十为刚柔之德（地道，有形）；以成数运于生数之上，天地交感，吉凶叶应。","category":"guide","aliases":["正易心法第三十八章","卦位生数运以成数","生成之数感应之道"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-38.md","filePath":"yijing/zheng-yi-xin-fa/chapter-38.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-38.md"},x=r({...c,setup(u){const i=[{id:"z38-01",label:"一、生数与成数",showLabel:!0,sentences:[["卦位",{text:"生数",glossary:"shengshu"},"，运以",{text:"成数",glossary:"chengshu"},"。生成之数，",{text:"感应之道",glossary:"ganyingZhidao"},"。"]],note:["卦的位置对应生数，用成数来运转；生数与成数，是天地感应之道。（**本章极短，却是全书少见的「枢纽章」**：**前面讲数是「是什么」，本章讲数是「怎么作用」——从数理过渡到感应。**「没有感应，数只是数；有了感应，数才能知吉凶。」）"]},{id:"z38-02",label:"二、天道与地道",showLabel:!0,sentences:[["生数，谓一二三四五，",{text:"阴阳之位",glossary:"yinyangZhiwei"},"也，天道也。成数，谓六七八九十，",{text:"刚柔之德",glossary:"gangrouZhide"},"也，地道也。"]],note:["生数，是一二三四五，是阴阳的位置，是天道；成数，是六七八九十，是刚柔的德性，是地道。（**这一对区分值得细读**：**阴阳＝气的方向**（升／降、聚／散），是**天道**的属性，无形只有位置；**刚柔＝物的质地**（硬／软、动／静），是**地道**的属性，有形有质感。**生数提供坐标，成数提供物质。**）"]},{id:"z38-03",label:"三、天地交感",showLabel:!0,sentences:[["以刚柔成数，而运于阴阳生数之上，然后天地",{text:"交感",glossary:"jiaogan"},"，吉凶",{text:"叶应",glossary:"xieying"},"。而天下之事，无能逃于其间矣。"]],note:["用刚柔的成数，在阴阳生数之上运行，然后天地交感，吉凶协同感应，天下的事没有能逃出其中的。（**这一步是本章的核心机制**：「成数在生数上运行」——**静的是坐标（位），动的是德（运），两相运合就是「交感」。** 与第三十七章的「孕于」同理：**不是并列对应，而是「运行于其上」——有先后、有主从。**）"]},{id:"z38-04",label:"四、无形与有形",showLabel:!0,sentences:[["阴阳之位，有",{text:"象无形",glossary:"xiangWuxing"},"，在天也。刚柔则形，而以其在地也。"]],note:["阴阳之位，有象无形，属于天；刚柔则成形，属于地。（**「有象无形」四字是全章的落点**：**生数是「位」——可以感知但不可触摸；成数是「物」——落到实处可见。** 原文「有所无形」当为「有象无形」之讹。）"]}],p=[{id:"shengshu",term:"生数",pinyin:"shēng shù",meaning:"一二三四五，阴阳之位，天道。有象无形，提供坐标。"},{id:"chengshu",term:"成数",pinyin:"chéng shù",meaning:"六七八九十，刚柔之德，地道。有形可见，提供物质与运行。"},{id:"ganyingZhidao",term:"感应之道",pinyin:"gǎn yìng zhī dào",meaning:"感而遂通之道。天地之间因数而感应，吉凶因此呼应。"},{id:"yinyangZhiwei",term:"阴阳之位",pinyin:"yīn yáng zhī wèi",meaning:"阴阳的位置。生数定位，是天道的坐标。"},{id:"gangrouZhide",term:"刚柔之德",pinyin:"gāng róu zhī dé",meaning:"刚柔的德性。成数显德，是地道的品质。"},{id:"jiaogan",term:"交感",pinyin:"jiāo gǎn",meaning:"天地相互感应。生数（天）与成数（地）相运合。"},{id:"xieying",term:"叶应",pinyin:"xié yìng",meaning:"协同感应。叶＝协。天地交感之后，吉凶自然呼应。"},{id:"xiangWuxing",term:"有象无形",pinyin:"yǒu xiàng wú xíng",meaning:"有气象但无实体。天道：可感知但不可触摸。原文作「有所无形」，当为「有象无形」。"}];return(b,n)=>{const l=a("DaoTextReading"),o=a("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=t(`<h1 id="正易心法·第三十八章" tabindex="-1">正易心法·第三十八章 <a class="header-anchor" href="#正易心法·第三十八章" aria-label="Permalink to &quot;正易心法·第三十八章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章的核心命题：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>生数（1-5）＝ 天道 ＝ 阴阳之位 ＝ 有象无形 ＝ 坐标（静）</span></span>
<span class="line"><span>成数（6-10）＝ 地道 ＝ 刚柔之德 ＝ 刚柔则形 ＝ 运动（动）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>以成数运于生数之上 → 天地交感 → 吉凶叶应 → 天下之事无能逃于其间</span></span></code></pre></div><p><strong>本章的位置</strong>：<strong>前面几章讲数「是什么」，本章讲数「怎么作用」</strong>——<strong>这是全书从「数理」过渡到「感应」的枢纽。</strong></p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>天道与地道的四重对比</strong>：</p><table tabindex="0"><thead><tr><th>维度</th><th>天道（生数）</th><th>地道（成数）</th></tr></thead><tbody><tr><td>数字范围</td><td>1–5</td><td>6–10</td></tr><tr><td>属性</td><td>阴阳之位</td><td>刚柔之德</td></tr><tr><td>形态</td><td>有象无形</td><td>刚柔则形</td></tr><tr><td>功能</td><td>定位（坐标）</td><td>运行（动力）</td></tr><tr><td>哲学层次</td><td>本体（体）</td><td>现象（用）</td></tr><tr><td>时间性</td><td>先（生）</td><td>后（成）</td></tr><tr><td>空间性</td><td>在天</td><td>在地</td></tr></tbody></table><p><strong>「阴阳」与「刚柔」为什么要分开说？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>《系辞》的三才框架：</span></span>
<span class="line"><span>  天道：阴阳（无形，方向性）</span></span>
<span class="line"><span>  地道：刚柔（有形，质地性）</span></span>
<span class="line"><span>  人道：仁义（有为，价值性）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>麻衣强调这个区分，是因为易学中常见的混淆：</span></span>
<span class="line"><span>  把「阴阳」和「刚柔」当作同一件事</span></span>
<span class="line"><span></span></span>
<span class="line"><span>实际上：</span></span>
<span class="line"><span>  阴阳 = 气的方向（升/降、聚/散）</span></span>
<span class="line"><span>  刚柔 = 物的质地（硬/软、动/静）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>生数（天/阴阳）提供坐标，成数（地/刚柔）提供物质</span></span>
<span class="line"><span>两者相运，才有具体的事物和吉凶</span></span></code></pre></div><p><strong>「无能逃于其间」</strong>——这是本章最强的宣称：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>为什么「无能逃」？</span></span>
<span class="line"><span>  因为任何事物，都同时具有「位」（在哪里）与「运」（如何运动）两个维度</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  「位」= 生数管辖</span></span>
<span class="line"><span>  「运」= 成数管辖</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  没有「位」的事物不存在，没有「运」的事物不变化</span></span>
<span class="line"><span>  而存在与变化，已经穷尽了「事」的所有可能</span></span></code></pre></div><p><strong>联系第三十六章</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>「卦数占卦，理之自然」</span></span>
<span class="line"><span>= 任何数 % 8 → 卦（位）；任何数 % 6 → 爻（运）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>这正是「无能逃」的操作化：</span></span>
<span class="line"><span>  任何信息，都能被映射到生数（位）与成数（运）的坐标系里</span></span></code></pre></div><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先把天道／地道两列对照看：<strong>位与德、无形与有形</strong>；</li><li>再看「以成数运于生数之上」——<strong>静的是坐标，动的是德</strong>；</li><li>最后读「无能逃于其间」——<strong>这是本章最强的宣称。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>生数（天道）</strong>：1–5，阴阳之位，有象无形。</li><li><strong>成数（地道）</strong>：6–10，刚柔之德，刚柔则形。</li><li><strong>运以成数</strong>：成数在生数之上运行。</li><li><strong>天地交感</strong>：两者相遇，产生感应。</li><li><strong>吉凶叶应</strong>：感应的结果显现为吉凶。</li><li><strong>无能逃</strong>：万事皆在生成数的感应之道中。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,19)),e(l,{colophon:"卦位生数 · 运以成数 · 天地交感 · 感应之道",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第三十八章原文",sections:i,glossary:p}),n[1]||(n[1]=s("blockquote",null,[s("p",null,"注：本页依所据底本录入。原文「有所无形」当为「有象无形」之讹，此处说明而不径改。")],-1)),n[2]||(n[2]=s("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),s("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(o,{items:[{term:"生数（天道）",pinyin:["shēng","shù"],meaning:"一二三四五，阴阳之位——有象无形，是天道的坐标。"},{term:"成数（地道）",pinyin:["chéng","shù"],meaning:"六七八九十，刚柔之德——刚柔则形，是地道的品质与运行。"},{term:"阴阳与刚柔",pinyin:["gāng","róu"],meaning:"阴阳＝气的方向（内在、无形）；刚柔＝物的质地（外在、有形）。麻衣强调此区分不可混。"},{term:"感应之道",pinyin:["gǎn","yìng"],meaning:"感而遂通之道。成数运于生数之上，天地交感，吉凶因此呼应。"},{term:"无能逃于其间",pinyin:["wú","néng"],meaning:"万事皆兼「位」（生数）与「运」（成数）两个维度——两者穷尽了「事」的所有可能。"}]}),n[3]||(n[3]=t(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章的核心命题：<strong>生数为天道（阴阳之位，有象无形），成数为地道（刚柔之德，刚柔则形）；以成数运于生数之上，天地交感，吉凶叶应。</strong></p><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>「阴阳」与「刚柔」为什么要分开说？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>《系辞》三才框架：</span></span>
<span class="line"><span>  天道：阴阳（无形，方向性）  地道：刚柔（有形，质地性）  人道：仁义（有为，价值性）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>阴阳 = 气的方向（升/降、聚/散）</span></span>
<span class="line"><span>刚柔 = 物的质地（硬/软、动/静）</span></span>
<span class="line"><span></span></span>
<span class="line"><span>生数（天/阴阳）提供坐标，成数（地/刚柔）提供物质</span></span>
<span class="line"><span>两者相运，才有具体的事物和吉凶</span></span></code></pre></div><p><strong>「无能逃于其间」为什么成立？</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>任何事物都同时具有「位」（在哪里）与「运」（如何运动）</span></span>
<span class="line"><span>「位」= 生数管辖；「运」= 成数管辖</span></span>
<span class="line"><span>没有「位」的事物不存在，没有「运」的事物不变化</span></span>
<span class="line"><span>而存在与变化，已穷尽了「事」的所有可能</span></span></code></pre></div><p><strong>联系第三十六章</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>「卦数占卦，理之自然」</span></span>
<span class="line"><span>= 任何数 % 8 → 卦（位）；任何数 % 6 → 爻（运）</span></span>
<span class="line"><span>这正是「无能逃」的操作化</span></span></code></pre></div><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>对照两列：<strong>位与德、无形与有形、静与动</strong>；</li><li>记住这个次序：<strong>先有坐标，再有运行</strong>；</li><li>顺着钩子想（承接昇哥的问题）：<strong>「感应」的机制是什么？</strong> 物理学的回答是「力」——有明确的传递机制与距离衰减；<strong>易学的回答是「位与运的对应」——不需要接触，不需要媒介。</strong> 这两种「感应」，<strong>是同一件事的不同描述，还是完全不同的两件事？</strong> 我的看法：<strong>麻衣不会去做这个比较，因为在他看来「感应」根本不需要机制</strong>——<strong>天地交感如「同声相应、同气相求」，是「类」的自动呼应，不是「力」的传递。</strong> 但<strong>这个「自动呼应」恰恰是最难证成的一步</strong>：<strong>它预设了「同类相感」这条原理本身。</strong> 所以我的结论是：<strong>麻衣的「感应」不是一种「机制」，而是一种「秩序观」</strong>——<strong>世界被安排成「同类相感」的样子。</strong> 你可以不接受，但它内部是自洽的。</li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>卦的位置对应生数，用成数来运转；生数与成数，是天地感应之道。</p><p>生数，是一二三四五，是阴阳的位置，是天道；成数，是六七八九十，是刚柔的德性，是地道。</p><p>用刚柔的成数，在阴阳生数之上运行，然后天地交感，吉凶协同感应，天下的事，没有能逃出其中的。</p><p>阴阳之位，有象无形，属于天；刚柔则成形，属于地。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第三十八章把生数与成数分工了——<strong>一个给坐标，一个给动力；一个在天上，一个在地上。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「阴阳之位」与「刚柔之德」</strong>——<strong>这一对区分很要紧</strong>：阴阳是「位」（方向），刚柔是「德」（质地）。<strong>位在天上，德在地上。</strong> 麻衣把《系辞》「立天之道曰阴与阳，立地之道曰柔与刚」用到了数上。</li><li><strong>「运以成数」</strong>——<strong>静的坐标 + 动的德 = 世界</strong>。这让我想到第一章的「落处」：<strong>没有坐标，就不知道落在哪；没有运行，就没有变化。</strong></li><li><strong>「有象无形」</strong>——<strong>四个字说尽了天道的性质</strong>：可以感知，不能触摸。<strong>它像坐标系里的一个点：你知道它在哪，但你摸不到它。</strong></li><li><strong>「无能逃于其间」</strong>——这是本章最强的宣称。<strong>它的力量在于「位与运」确实覆盖了「事」的所有可能</strong>；<strong>它的软肋在于，「覆盖」也可以是定义出来的覆盖。</strong></li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>「感应」的机制是什么？</strong> 物理学的回答是「力」——有传递机制与距离衰减；<strong>易学的回答是「位与运的对应」——不需要接触，不需要媒介。</strong> 我的看法：<strong>麻衣不会做这个比较，因为在他看来「感应」根本不需要机制</strong>——<strong>「同声相应、同气相求」，是「类」的自动呼应。</strong> 但**「自动呼应」是最难证成的一步**：<strong>它预设了「同类相感」这条原理本身。</strong> 所以我的结论：<strong>麻衣的「感应」不是一种「机制」，而是一种「秩序观」</strong>——<strong>世界被安排成「同类相感」的样子。</strong> 你可以不接受，但它内部是自洽的。</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-37">第三十七章 · 须究落处</a> — 五行生数成数（本章说其运行机制）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-36">第三十六章 · 策数六八</a> — 「卦数占卦」（本章「无能逃」的操作化）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-39">第三十九章</a> — 「一变为七，七变为九」（生成之数的变化周期）</li><li><a href="/Dao/yijing/shi-yi/xi-ci-zhuan-shang">系辞上传</a> — 「立天之道曰阴与阳，立地之道曰柔与刚」</li></ul>`,23))])}}});export{m as __pageData,x as default};
